def lz77_encode(data, window=4096, max_len=18):
    i, out = 0, []
    while i < len(data):
        best_d, best_l = 0, 0
        for j in range(max(0, i - window), i):  # 탐색 버퍼
            l = 0
            while (l < max_len and i + l < len(data) - 1
                   and data[j + l] == data[i + l]):
                l += 1  # 겹침(j + l ≥ i)도 허용
            if l > best_l:
                best_d, best_l = i - j, l
        out.append((best_d, best_l, data[i + best_l]))
        i += best_l + 1  # 일치 길이 + 다음 문자만큼 이동
    return out

def lz77_decode(tokens):
    out = []
    for d, l, ch in tokens:
        for _ in range(l):
            out.append(out[-d])  # 거리 d 앞에서 1글자씩 복사
        out.append(ch)
    return ''.join(out)

lz78.pseudocode:
def lz78_encode(data):
    dictionary = {'': 0}  # 구문 → 색인
    out, phrase = [], ''
    for ch in data:
        if phrase + ch in dictionary:
            phrase += ch  # 사전에 있으면 계속 확장
        else:
            out.append((dictionary[phrase], ch))
            # 새 구문 등록 (복호기도 같은 순서로 등록)
            dictionary[phrase + ch] = len(dictionary)
            phrase = ''
    if phrase:  # 끝에 남은 구문
        out.append((dictionary[phrase], ''))
    return out

def lz78_decode(tokens):
    phrases, out = [''], []
    for idx, ch in tokens:
        p = phrases[idx] + ch
        phrases.append(p)  # 같은 사전을 스스로 재구성
        out.append(p)
    return ''.join(out)

lzw.pseudocode:
def lzw_encode(data, alphabet):
    dic = {ch: i for i, ch in enumerate(alphabet)}
    w, out = '', []
    for c in data:
        if w + c in dic:
            w += c  # 사전에 있는 가장 긴 문자열까지 확장
        else:
            out.append(dic[w])  # 색인만 출력
            dic[w + c] = len(dic)  # 새 문자열 등록
            w = c
    if w:
        out.append(dic[w])
    return out

def lzw_decode(codes, alphabet):
    dic = {i: ch for i, ch in enumerate(alphabet)}
    w = dic[codes[0]]
    out = [w]
    for k in codes[1:]:
        # 아직 등록 전인 코드(KwKwK 경우) 처리
        entry = dic[k] if k in dic else w + w[0]
        out.append(entry)
        dic[len(dic)] = w + entry[0]
        w = entry
    return ''.join(out)
